export function NewsletterSignup({
  heading = "{{heading}}",
  microcopy = "{{microcopy}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
}) {
  const stacked = layout === "stacked";
  return (
    <form style={{ font: "15px system-ui, sans-serif", color: "#241430", display: "flex", gap: 16, padding: 20,
      background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 14, maxWidth: 460,
      flexDirection: stacked ? "column" : "row", alignItems: stacked ? "stretch" : "center" }}>
      <div>
        <p style={{ margin: "0 0 4px", fontWeight: 700, fontSize: 16 }}>{heading}</p>
        <p style={{ margin: 0, fontSize: 13, color: "#241430aa" }}>{microcopy}</p>
      </div>
      <div style={{ display: "flex", gap: 8, flexDirection: stacked ? "column" : "row" }}>
        <label htmlFor="news-email" style={{ position: "absolute", width: 1, height: 1, overflow: "hidden" }}>Email address</label>
        <input id="news-email" type="email" name="email" placeholder="you@example.com" required
          style={{ flex: 1, font: "inherit", padding: "9px 12px", border: "1px solid #24143033", borderRadius: 8, minWidth: 0 }} />
        <button type="submit" style={{ border: "none", color: "#241430", padding: "9px 18px", borderRadius: 8,
          fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap", background: accent }}>Subscribe</button>
      </div>
    </form>
  );
}
